#!/bin/sh
# layer-2 load audit -- dart -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_dart.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_dart
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_dart.txt
: > "$OUT"
echo "=== layer-2 load audit -- dart ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! test -x /persist/dart-sdk/bin/dart >/dev/null 2>&1; then
  echo "dart: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- nothing.dynamic null.null
D=$ROOT/p1; mkdir -p "$D"; cd "$D"
cat > main.dart <<'L2_SRC_EOF'

void main() {
  dynamic v = null;
  print("nothing.dynamic null.null" + "|" + (v.toString()));
}
L2_SRC_EOF
V=ok
if [ "$V" = ok ]; then
  if timeout 30 /persist/dart-sdk/bin/dart run main.dart > run.out 2> run.err; then :; else
    if [ "$(grep -c "|" run.out)" = 0 ]; then V="<compile-error>"; else V="<aborted>"; fi
  fi
  grep -F "nothing.dynamic null.null|" run.out >> "$OUT" || V="${V}"
fi
grep -qF "nothing.dynamic null.null|" "$OUT" || echo "nothing.dynamic null.null|$V" >> "$OUT"

